INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('topic:KURS320-026','topic','','BIOS/UEFI: brak wpisu Windows Boot Manager','UEFI missing Windows Boot Manager entry','description: Ustal tryb UEFI/Legacy, styl partycji, kolejność startu, obecność EFI System Partition, BCD i status BitLocker. symptoms: Dysk jest widoczny w UEFI, ale komputer zgłasza brak urządzenia rozruchowego lub uruchamia niewłaściwy system. diagnosis: Ustal tryb UEFI/Legacy, styl partycji, kolejność startu, obecność EFI System Partition, BCD i status BitLocker. repair: Zabezpiecz dane, potwierdź klucz BitLocker i użyj WinRE/Startup Repair zgodnie z dokumentacją. Nie formatuj partycji EFI w ciemno.','descriptionEn: Identify UEFI/Legacy mode, partition style, boot order, EFI System Partition, BCD and BitLocker status. symptomsEn: The drive appears in UEFI, but the PC reports no boot device or starts the wrong operating system. diagnosisEn: Identify UEFI/Legacy mode, partition style, boot order, EFI System Partition, BCD and BitLocker status. repairEn: Protect data, confirm the BitLocker recovery key and use WinRE/Startup Repair according to documentation. Do not blindly format the EFI partition. stepEn: Start with the following evidence-led repair path: Protect data, confirm the BitLocker recovery key and use WinRE/Startup Repair according to documentation. Do not blindly format the EFI partition. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-027','topic','','BIOS update: weryfikacja pliku i odzyskiwanie','BIOS update file verification and recovery planning','description: Zweryfikuj model, SKU, rewizję płyty, wersję, hash i podpis pakietu. Ustal czy producent udostępnia procedurę BIOS recovery. symptoms: Po aktualizacji firmware laptop nie startuje, pojawia się komunikat o niezgodnym obrazie lub aktualizacja została przerwana. diagnosis: Zweryfikuj model, SKU, rewizję płyty, wersję, hash i podpis pakietu. Ustal czy producent udostępnia procedurę BIOS recovery. repair: Stosuj tylko oficjalny plik dla dokładnego modelu i instrukcję OEM. W razie niepowodzenia nie próbuj losowych plików ani kombinacji klawiszy.','descriptionEn: Verify model, SKU, board revision, version, hash and package signature. Determine whether the manufacturer provides a BIOS recovery procedure. symptomsEn: After a firmware update, the laptop does not boot, reports an incompatible image or the update was interrupted. diagnosisEn: Verify model, SKU, board revision, version, hash and package signature. Determine whether the manufacturer provides a BIOS recovery procedure. repairEn: Use only the official file for the exact model and OEM instructions. If it fails, do not try random files or key combinations. stepEn: Start with the following evidence-led repair path: Use only the official file for the exact model and OEM instructions. If it fails, do not try random files or key combinations. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-028','topic','','TPM i BitLocker po zmianie BIOS','TPM and BitLocker after BIOS changes','description: Porównaj PCR/Secure Boot, TPM, tryb startu i historię zmian. Sam monit odzyskiwania nie dowodzi uszkodzenia dysku. symptoms: Po aktualizacji BIOS lub zmianie Secure Boot system prosi o klucz odzyskiwania BitLocker. diagnosis: Porównaj PCR/Secure Boot, TPM, tryb startu i historię zmian. Sam monit odzyskiwania nie dowodzi uszkodzenia dysku. repair: Poproś właściciela o odzyskanie klucza z jego konta/organizacji. Po odblokowaniu sprawdź stan szyfrowania i przyczynę zmiany pomiarów rozruchu.','descriptionEn: Compare PCR/Secure Boot, TPM, boot mode and change history. A recovery prompt alone does not prove drive failure. symptomsEn: After a BIOS update or Secure Boot change, Windows requests a BitLocker recovery key. diagnosisEn: Compare PCR/Secure Boot, TPM, boot mode and change history. A recovery prompt alone does not prove drive failure. repairEn: Ask the owner to retrieve the key from their account or organization. After unlock, check encryption status and why boot measurements changed. stepEn: Start with the following evidence-led repair path: Ask the owner to retrieve the key from their account or organization. After unlock, check encryption status and why boot measurements changed. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-029','topic','','RTC/CMOS: reset daty i utrata ustawień','RTC/CMOS: clock reset and lost settings','description: Sprawdź baterię RTC, złącze, przewody i pobór w stanie bez zasilania. W laptopach bateria może być przewodowa lub zintegrowana. symptoms: Zegar systemowy resetuje się, BIOS traci ustawienia lub po odłączeniu zasilania pojawia się błąd daty. diagnosis: Sprawdź baterię RTC, złącze, przewody i pobór w stanie bez zasilania. W laptopach bateria może być przewodowa lub zintegrowana. repair: Wymień wyłącznie część o właściwym typie, napięciu, złączu i polaryzacji, zgodnie z instrukcją. Zapisz ustawienia firmware przed pracą.','descriptionEn: Check the RTC cell, connector, cable and standby drain. Laptop RTC batteries may be wired or integrated. symptomsEn: The system clock resets, BIOS loses settings or a date error appears after power is removed. diagnosisEn: Check the RTC cell, connector, cable and standby drain. Laptop RTC batteries may be wired or integrated. repairEn: Replace only a part with the correct type, voltage, connector and polarity according to the manual. Record firmware settings before service. stepEn: Start with the following evidence-led repair path: Replace only a part with the correct type, voltage, connector and polarity according to the manual. Record firmware settings before service. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-030','topic','','EC/KBC: brak reakcji klawiatury i sekwencji startu','EC/KBC: keyboard and power-sequence failure','description: Rozdziel brak zasilania standby, sygnał przycisku, stan baterii, firmware EC, komunikację z BIOS i uszkodzenie klawiatury. symptoms: Laptop nie reaguje prawidłowo na przycisk, diody zachowują się nietypowo lub klawiatura nie działa przed startem systemu. diagnosis: Rozdziel brak zasilania standby, sygnał przycisku, stan baterii, firmware EC, komunikację z BIOS i uszkodzenie klawiatury. repair: Pracuj według schematu dokładnej rewizji. Weryfikuj wersję firmware i procedurę producenta; programowanie EC należy do doświadczonego technika.','descriptionEn: Separate missing standby power, power-button signal, battery state, EC firmware, BIOS communication and keyboard faults. symptomsEn: The laptop does not respond correctly to the power button, LEDs behave unusually or the keyboard fails before OS startup. diagnosisEn: Separate missing standby power, power-button signal, battery state, EC firmware, BIOS communication and keyboard faults. repairEn: Work from the schematic for the exact board revision. Verify firmware version and OEM procedure; EC programming is for an experienced technician. stepEn: Start with the following evidence-led repair path: Work from the schematic for the exact board revision. Verify firmware version and OEM procedure; EC programming is for an experienced technician. Record the baseline condition and repeat the original test after any change.','',''),
('article:HANDBOOK-12-01','article','','Centrum połączeń i obliczeń','','body: 01 / PŁYTA GŁÓWNA I CPU Centrum połączeń i obliczeń Jak to działa Płyta łączy podzespoły, a CPU wykonuje instrukcje. Do startu potrzebne są także właściwe zasilanie, firmware i sprawna pamięć. Typowe objawy Brak reakcji, restart lub brak POST mają wiele możliwych przyczyn. Pracujący wentylator nie potwierdza sprawności procesora. Pierwszy bezpieczny test Zanotuj model, kontrolki i kody diagnostyczne; odłącz akcesoria. Porównaj sygnały z instrukcją producenta. Budowa od środka Na płycie znajdują się gniazda, układy sterujące, sekcje zasilania i ścieżki sygnałowe. CPU w komputerze stacjonarnym bywa wymienny, w laptopie często jest wlutowany. Przed wymianą Sprawdź dokładny model płyty, rewizję, gniazdo i listę zgodnych procesorów. Sama zgodność fizycznego gniazda nie gwarantuje obsługi przez firmware. Częsty błąd Wymiana CPU tylko dlatego, że ekran pozostaje czarny. Najpierw ustal, czy komputer przechodzi POST oraz czy działa tor obrazu. Kiedy do serwisu Gdy występuje korozja, nadpalenie, uszkodzone gniazdo albo podejrzenie usterki sekcji zasilania lub układu wlutowanego. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-02','article','','Pamięć używana podczas pracy','','body: 02 / PAMIĘĆ RAM Pamięć używana podczas pracy Jak to działa RAM przechowuje tymczasowo dane uruchomionych programów. Po wyłączeniu zasilania jej zawartość znika. Typowe objawy Błędy testu pamięci, zawieszanie i brak POST mogą wskazywać na moduł, gniazdo lub inne elementy platformy. Pierwszy bezpieczny test Sprawdź kod diagnostyczny producenta i zgodność modułu. Przed dłuższą diagnostyką zabezpiecz ważne dane. Budowa od środka Moduł zawiera układy pamięci na płytce drukowanej; komputer korzysta także z kontrolera pamięci. W laptopach spotkasz SO-DIMM lub pamięć wlutowaną. Przed wymianą Zweryfikuj generację DDR, format, pojemność i obsługę przez model. Nie wciskaj modułu do niepasującego gniazda; wymieniaj go tylko po odłączeniu zasilania. Częsty błąd Uznawanie każdego czarnego ekranu za uszkodzoną pamięć. Podobny objaw daje też niesprawny wyświetlacz lub problem z uruchomieniem płyty. Kiedy do serwisu Gdy pamięć jest wlutowana, gniazdo wygląda na uszkodzone albo zgodne, sprawne moduły nadal powodują błędy. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-03','article','','Dysk i bezpieczeństwo danych','','body: 03 / SSD I HDD Dysk i bezpieczeństwo danych Jak to działa SSD zapisuje dane w pamięci flash, a HDD na talerzach. SATA i NVMe korzystają z różnych interfejsów. Typowe objawy Błędy odczytu, znikanie nośnika i wolny start wymagają diagnostyki. Klikający HDD może być w trakcie awarii mechanicznej. Pierwszy bezpieczny test Najpierw zabezpiecz ważne dane, jeśli nośnik odpowiada. Potem sprawdź wykrywanie w UEFI i dostępne informacje SMART. Budowa od środka SSD ma kontroler i kości flash; HDD zawiera ruchome talerze oraz głowice. Nośniki M.2 mogą różnić się protokołem mimo podobnego wyglądu. Przed wymianą Sprawdź interfejs, długość M.2 lub rozmiar obudowy, możliwość montażu oraz plan kopii i odtworzenia danych. Częsty błąd Wielokrotne uruchamianie testów i reinstalacja systemu na nośniku, z którego trzeba najpierw odzyskać dane. Kiedy do serwisu Gdy dysk klika, wielokrotnie znika lub zawiera jedyną kopię ważnych plików. Ogranicz kolejne próby odczytu. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-04','article','','GPU i droga obrazu','','body: 04 / UKŁAD GRAFICZNY GPU i droga obrazu Jak to działa GPU przygotowuje obraz. Może być zintegrowany, osobny lub współpracować z układem przełączającym wyświetlanie. Typowe objawy Artefakty, błędy sterownika lub brak obrazu nie potwierdzają samodzielnie uszkodzenia GPU. Pierwszy bezpieczny test Sprawdź drugi monitor i przewód. Zanotuj, czy zakłócenia pojawiają się jeszcze przed startem systemu. Budowa od środka Układ graficzny współpracuje z pamięcią, zasilaniem i chłodzeniem. W komputerze stacjonarnym karta może być osobnym modułem; w laptopie układ bywa wlutowany. Przed wymianą Dla karty stacjonarnej sprawdź złącze, miejsce w obudowie, wymagania zasilania i zgodność wyjść obrazu. Częsty błąd Podgrzewanie układu „na próbę” albo długie obciążanie komputera, który już wyłącza się z powodu temperatury. Kiedy do serwisu Gdy artefakty występują na różnych ekranach przed uruchomieniem systemu lub podejrzany jest układ wlutowany. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-05','article','','Matryca, podświetlenie i taśma','','body: 05 / EKRAN Matryca, podświetlenie i taśma Jak to działa Panel odbiera sygnał obrazu przez taśmę i złącze; podświetlenie umożliwia jego oglądanie. Typowe objawy Pęknięcie, pasy, migotanie przy ruchu pokrywy i bardzo ciemny ekran mogą mieć odmienne przyczyny. Pierwszy bezpieczny test Sprawdź jasność, wybrane wyjście obrazu i monitor zewnętrzny. Zanotuj, czy komputer rzeczywiście się uruchamia. Budowa od środka Zespół ekranu obejmuje panel, podświetlenie, taśmę i często ramkę oraz zawiasy. Uszkodzenie zawiasu może obciążać taśmę. Przed wymianą Potwierdź numer panelu, rozmiar, rozdzielczość, typ i położenie złącza oraz sposób mocowania. Podobny ekran nie musi pasować. Częsty błąd Odłączanie taśmy przy podłączonej baterii albo uznawanie działającego monitora zewnętrznego za dowód uszkodzenia samej matrycy. Kiedy do serwisu Gdy trzeba rozbierać delikatną pokrywę, uszkodzone jest złącze lub występują ślady cieczy. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-06','article','','Skąd komputer bierze energię','','body: 06 / ZASILACZ I WEJŚCIE ZASILANIA Skąd komputer bierze energię Jak to działa Zasilacz dostarcza energię. Zgodność wtyku, parametrów i — przy USB‑C — obsługi właściwego profilu zasilania jest niezbędna. Typowe objawy Brak reakcji, przerywane ładowanie lub wyłączanie pod obciążeniem mogą wynikać z kabla, gniazda albo elektroniki. Pierwszy bezpieczny test Sprawdź gniazdko, stan przewodu, oznaczenia zgodności i kontrolki. Nie używaj uszkodzonego kabla. Budowa od środka Zewnętrzna ładowarka lub zasilacz PC współpracuje z przewodem i wejściem komputera. Wewnątrz zasilacza mogą utrzymywać się niebezpieczne napięcia. Przed wymianą Dobierz urządzenie według specyfikacji producenta: napięcia, wymaganej mocy i właściwego złącza. Samo dopasowanie wtyku nie wystarcza. Częsty błąd Zakładanie, że każdy kabel i zasilacz USB‑C zapewnia te same funkcje, lub otwieranie obudowy zasilacza. Kiedy do serwisu Przy nadpaleniu, iskrzeniu, luźnym gnieździe albo podejrzeniu uszkodzenia wewnętrznego toru zasilania. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-07','article','','Akumulator i ładowanie','','body: 07 / BATERIA Akumulator i ładowanie Jak to działa Bateria magazynuje energię, a elektronika urządzenia zarządza jej ładowaniem i użytkowaniem. Typowe objawy Krótki czas pracy i brak ładowania mogą wynikać z baterii, ustawionego limitu ładowania lub zasilacza. Pierwszy bezpieczny test Sprawdź ustawienia i zgodność ładowarki. W Windows raport stanu baterii można utworzyć poleceniem powercfg /batteryreport. Budowa od środka Pakiet obejmuje ogniwa, elektronikę ochronną i złącze. Jego kształt oraz sposób montażu zależą od modelu laptopa. Przed wymianą Sprawdź numer części, zgodność elektryczną i mechaniczną oraz instrukcję serwisową. Nie używaj pakietu o niepewnym pochodzeniu. Częsty błąd Ignorowanie limitu ładowania w ustawieniach lub wielokrotne podłączanie spuchniętej baterii „dla sprawdzenia”. Kiedy do serwisu Przy spuchnięciu, uszkodzeniu mechanicznym, zapachu, silnym nagrzewaniu lub trudno dostępnej baterii wewnętrznej. Nie ładuj uszkodzonego pakietu. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-08','article','','Wentylator, radiator i temperatura','','body: 08 / CHŁODZENIE Wentylator, radiator i temperatura Jak to działa Radiator odbiera ciepło, a wentylator przepycha powietrze. Materiał termiczny wspomaga kontakt między powierzchniami. Typowe objawy Hałas, spadek wydajności i wyłączenia mogą wskazywać na niedrożny wylot lub niesprawne chłodzenie. Pierwszy bezpieczny test Odsłoń wloty powietrza, sprawdź obciążenie systemu i temperatury. Przy nagłym wyłączaniu przerwij testy. Budowa od środka Zestaw może składać się z wentylatora, rurek cieplnych, radiatora oraz pasty lub termopadów o określonej grubości. Przed wymianą Dobierz część do numeru modelu i rozmieszczenia mocowań. Nie zastępuj termopadów przypadkową grubością. Częsty błąd Zakładanie, że sama wymiana pasty naprawi wentylator, albo blokowanie wirnika podczas pracy. Kiedy do serwisu Gdy wentylator ociera, laptop regularnie gaśnie lub demontaż układu wymaga rozebrania znacznej części urządzenia. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-09','article','','USB, HDMI i połączenia','','body: 09 / PORTY I ZŁĄCZA USB, HDMI i połączenia Jak to działa Porty przenoszą dane, obraz lub zasilanie. Podobne złącza USB‑C mogą obsługiwać różne funkcje. Typowe objawy Przerywane połączenie może wynikać z kabla, ustawień, urządzenia albo mechanicznego uszkodzenia gniazda. Pierwszy bezpieczny test Porównaj sprawny kabel i drugie urządzenie. Sprawdź specyfikację portu i obejrzyj złącze bez używania metalowych narzędzi. Budowa od środka Gniazdo ma styki oraz mocowanie do obudowy lub płytki. Sygnały przechodzą przez kontrolery i obwody zabezpieczające. Przed wymianą Sprawdź dokładny typ i układ pinów oraz czy port jest częścią osobnej płytki, czy płyty głównej. Częsty błąd Przypisywanie brakującego obrazu z USB‑C awarii, mimo że dany port nie obsługuje wyjścia wideo. Kiedy do serwisu Przy luźnym, nadpalonym lub wyrwanym gnieździe. Przestań go używać, szczególnie jeśli służy do ładowania. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-10','article','','Sterowanie komputerem','','body: 10 / KLAWIATURA I TOUCHPAD Sterowanie komputerem Jak to działa Klawiatura i touchpad przekazują polecenia przez kontrolery i połączenia z płytą. Touchpad może mieć osobny przełącznik. Typowe objawy Pojedynczy niedziałający klawisz, brak reakcji całej klawiatury i awaria touchpada wymagają różnych sprawdzeń. Pierwszy bezpieczny test Sprawdź ustawienia i urządzenie zewnętrzne. Po zalaniu wyłącz sprzęt i nie uruchamiaj go ponownie. Budowa od środka Pod klawiszami znajdują się mechanizmy i warstwy przewodzące. Touchpad ma powierzchnię czujnika oraz taśmę połączeniową. Przed wymianą Potwierdź model, układ klawiszy, typ podświetlenia i sposób mocowania; w niektórych laptopach klawiatura stanowi część obudowy. Częsty błąd Odrywanie klawiszy lub dalsze testowanie laptopa po zalaniu, zanim zostanie bezpiecznie oceniony. Kiedy do serwisu Po kontakcie z cieczą, przy uszkodzonej taśmie lub gdy wymiana wymaga demontażu wielu elementów obudowy. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-11','article','','Karta sieciowa i połączenie','','body: 11 / WI‑FI I SIEĆ Karta sieciowa i połączenie Jak to działa Karta łączy komputer z routerem przez anteny. Dostęp do internetu zależy również od działania samej sieci. Typowe objawy Brak sieci, słaby sygnał lub połączenie bez internetu mogą wynikać z routera, ustawień lub sterownika. Pierwszy bezpieczny test Sprawdź sieć na drugim urządzeniu i wyłącz tryb samolotowy. Jeśli możesz, porównaj połączenie przewodowe. Budowa od środka Moduł radiowy współpracuje z antenami, często umieszczonymi w pokrywie laptopa. Bluetooth może korzystać z tego samego modułu. Przed wymianą Potwierdź format modułu, zgodność platformy i liczbę złączy antenowych. Nie ciągnij anten za przewody. Częsty błąd Wymiana karty, gdy problem występuje także na telefonie połączonym z tym samym routerem. Kiedy do serwisu Gdy złącza antenowe są urwane, moduł jest wlutowany albo uszkodzona jest antena w pokrywie. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-12','article','','Głośniki, mikrofon i wyjścia audio','','body: 12 / DŹWIĘK Głośniki, mikrofon i wyjścia audio Jak to działa System wybiera wejście i wyjście dźwięku: głośniki, słuchawki, HDMI lub Bluetooth. Typowe objawy Cisza, trzaski lub niedziałający mikrofon mogą wynikać z ustawień, sterownika, przewodu lub gniazda. Pierwszy bezpieczny test Sprawdź wybrane urządzenie, głośność i uprawnienia mikrofonu. Porównaj wbudowane głośniki ze słuchawkami. Budowa od środka Tor audio obejmuje kontroler, wzmacniacz, głośniki, mikrofon oraz ewentualne gniazdo słuchawkowe. Przed wymianą Sprawdź numer części, położenie głośnika i typ przewodu. Najpierw wyklucz błędnie wybrane wyjście dźwięku. Częsty błąd Wymiana głośników, kiedy system przesyła dźwięk do monitora HDMI albo urządzenia Bluetooth. Kiedy do serwisu Przy uszkodzonym gnieździe, śladach cieczy albo braku dźwięku na wielu sprawnych urządzeniach po wykluczeniu ustawień. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-13','article','','Inspekcja','','body: Inspekcja Potwierdź model i objaw. Oceń uszkodzenia, ciecz i stan baterii. Przy zagrożeniu nie włączaj sprzętu. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-14','article','','Zasilanie','','body: Zasilanie Sprawdź gniazdko, kabel i zgodność zasilacza. Wewnętrzny tor zasilania ocenia serwis. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-15','article','','Standby','','body: Standby Technik sprawdza zasilanie spoczynkowe i sygnały na podstawie dokumentacji dokładnej płyty. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-16','article','','Start i POST','','body: Start i POST Zanotuj kody producenta i zachowanie kontrolek. Sam obrót wentylatora nie oznacza poprawnego POST. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-17','article','','Podzespół i objaw','','body: Podzespół i objaw Dobierz lekcję do objawu. Porównaj kabel, monitor lub urządzenie, zanim podejrzysz część. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-18','article','','Test końcowy','','body: Test końcowy Zweryfikuj pierwotny objaw oraz obraz, porty, sieć, ładowanie i chłodzenie. Zapisz wynik. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-SECTION-19','article','','Bezpieczeństwo przed każdą lekcją','','body: Bezpieczeństwo przed każdą lekcją Przed otwarciem wyłącz komputer i odłącz zasilanie. Wewnętrzną baterię odłączaj tylko zgodnie z instrukcją modelu. Nie otwieraj zasilacza ani pakietu baterii. Przy cieczy, korozji, nadpaleniu, dymie lub spuchniętej baterii przerwij pracę i nie włączaj sprzętu ponownie. Ciągłość i rezystancję mierzy się wyłącznie przy odłączonym zasilaniu. Pomiary odsłoniętej płyty pod napięciem, lutowanie i programowanie SPI wymagają przygotowania oraz właściwej dokumentacji — pozostaw je technikowi. Liczby z przykładowych plansz nie są mapą Twojego modelu. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:HANDBOOK-12-SECTION-20','article','','Od objawu do właściwej lekcji','','body: BIBLIOTEKA OBJAWÓW Od objawu do właściwej lekcji Wyszukaj problem i rozwiń podpowiedź. Pojedynczy objaw nie potwierdza awarii konkretnej części. Szukaj objawu Wyczyść Komputer nie włącza się Zacznij od gniazdka, przewodu i zgodnego zasilacza. Sprawdź lekcję o zasilaniu i ścieżkę diagnozy. Przy zapachu spalenizny przerwij próby. Błędy RAM lub brak POST Zanotuj kod diagnostyczny i sprawdź lekcję o RAM. Brak obrazu nie dowodzi uszkodzenia pamięci. Dysk znika lub działa wolno Najpierw zabezpiecz dane. Sprawdź wykrywanie dysku i SMART; przy klikającym HDD unikaj powtarzania testów. Brak obrazu lub artefakty Porównaj monitor zewnętrzny i przewód. Ustal, czy komputer przechodzi POST. Zobacz lekcje o ekranie i GPU. Bateria nie ładuje Sprawdź ustawiony limit ładowania i zgodność ładowarki. Spuchniętej baterii nie używaj ani nie ładuj. Przegrzewa się lub restartuje Sprawdź drożność wentylacji i obciążenie systemu. Gdy komputer nagle gaśnie, przerwij testy obciążeniowe. Nie działa Wi‑Fi Porównaj tę samą sieć na drugim urządzeniu i sprawdź tryb samolotowy. Zacznij od lekcji o Wi‑Fi. Nie działa port lub klawiatura Wypróbuj sprawny kabel lub urządzenie zewnętrzne. Po zalaniu nie uruchamiaj sprzętu ponownie. Brak dźwięku lub mikrofonu Sprawdź wybrane urządzenie, wyciszenie i uprawnienia mikrofonu. Porównaj głośniki ze słuchawkami. Zalanie, dym lub spuchnięta bateria Wyłącz urządzenie i odłącz zasilanie, jeśli jest to bezpieczne. Nie sprawdzaj, czy „jeszcze działa”. Przekaż sprzęt serwisowi. Brak pasującego tematu. Spróbuj krótszego hasła, np. „ekran”, „dysk” albo „bateria”. source: Podręcznik od zera – komponenty, diagnostyka i procedury','','','Podręcznik od zera – komponenty, diagnostyka i procedury'),
('article:COURSE-ONLINE-01','article','','Zanim zaczniesz','','body: 01 / BHP Zanim zaczniesz Wyłącz komputer, odłącz przewód i ładowarkę; baterię wewnętrzną odpinaj dopiero po bezpiecznym otwarciu. Pracuj na suchym blacie z odpowiednią ochroną ESD; dokumentuj ułożenie śrub i przewodów. Przy cieczy, dymie, nadpaleniu albo spuchniętej baterii przerwij próby uruchomienia. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-02','article','','Narzędzia na start','','body: 02 / WARSZTAT Narzędzia na start Przygotuj bity odpowiednie do modelu, plastikowy otwierak, pojemniki na śruby i miękką szczoteczkę. Przed użyciem multimetru sprawdź sondy, gniazda COM i V/Ω oraz wybrany tryb. IPA stosuj tylko bez zasilania; przed ponownym uruchomieniem pozwól jej całkowicie odparować. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-03','article','','Otwieranie laptopa i PC','','body: 03 / DEMONTAŻ Otwieranie laptopa i PC Sprawdź instrukcję serwisową: rozmieszczenie śrub, zatrzasków i kolejność demontażu. Otwieraj plastikowym narzędziem. Nie szarp taśm; po odsłonięciu płyty odłącz baterię. W komputerze stacjonarnym sfotografuj przewody przed ich wypięciem i oznacz długości śrub. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-04','article','','Pierwsze pomiary','','body: 04 / MULTIMETR Pierwsze pomiary Odczytaj wymagane napięcie i polaryzację z etykiety urządzenia; USB-C może negocjować różne napięcia. Przy napięciu DC użyj COM i V/Ω, nie gniazda pomiaru prądu. Nie dotykaj sondami sąsiednich styków. Przed sprawdzaniem ciągłości odłącz ładowarkę i baterię. Sam sygnał brzęczyka nie potwierdza sprawności podzespołu. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-05','article','','Od objawu do testu','','body: 05 / DIAGNOZA Od objawu do testu Rozróżnij brak zasilania, brak obrazu, brak POST i problem ze startem systemu. Przy czarnym ekranie sprawdź jasność i monitor zewnętrzny; przy błędach dysku najpierw zabezpiecz dane. Zapisuj objawy, kody błędów i wynik każdego testu. Nie wymieniaj części wyłącznie na podstawie domysłu. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-06','article','','Składanie i test końcowy','','body: 06 / WERYFIKACJA Składanie i test końcowy Przy odłączonym zasilaniu porównaj taśmy i złącza ze zdjęciami wykonanymi podczas demontażu. Załóż osłony wymagane do bezpiecznej pracy i zamknij obudowę zgodnie z instrukcją modelu. Sprawdź pierwotny objaw, start systemu, obraz, porty, sieć, ładowanie i działanie chłodzenia. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-07','article','','Inspekcja','','body: Inspekcja Ustal model i objaw. Obejrzyj obudowę, porty i ślady zalania. Uszkodzenia cieczą, nadpalenia i spuchnięte ogniwa oznaczają przerwanie pracy. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-08','article','','Wejście zasilania','','body: Wejście zasilania Sprawdź zgodność ładowarki, gniazdko, kabel i kontrolki. Śledzenie toru DC-IN, bezpiecznika i układu ładowania wymaga dokumentacji oraz przygotowania technicznego. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-09','article','','Standby','','body: Standby Technik sprawdza, czy pojawiają się linie zasilania spoczynkowego, zasilanie kontrolera EC i pamięci firmware. Oznaczenia oraz wartości zależą od płyty. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły'),
('article:COURSE-ONLINE-10','article','','Przycisk i start','','body: Przycisk i start Po naciśnięciu przycisku technik porównuje sygnały startowe z dokumentacją. Pracujący wentylator nie jest dowodem udanego POST. source: Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły','','','Kurs online – BHP, podstawy, diagnostyka i zaawansowane moduły');
